import io

import pytest

from youtube_dl.compat import compat_HTTPError
from youtube_dl.utils import ExtractorError, GeoRestrictedError

from youtube_dl.extractor.tvplay import ViafreeIE


URL = 'http://www.viafree.no/programmer/underholdning/det-beste-vorspielet/sesong-2/episode-1'
PATH = 'programmer/underholdning/det-beste-vorspielet/sesong-2/episode-1'
COUNTRY = 'no'
GUID = '757786'
STREAM_LINK_URL = 'https://stream.example.com/streamlink'
M3U8_URL = 'https://stream.example.com/path/master.m3u8'


class _FakeDownloader(object):
    params = {}


def _make_ie():
    ie = ViafreeIE()
    ie.set_downloader(_FakeDownloader())
    return ie


def _content_json():
    return {
        '_embedded': {
            'viafreeBlocks': [
                {'_embedded': {'program': {
                    'guid': GUID,
                    '_links': {'streamLink': {'href': STREAM_LINK_URL}},
