            'title': 'Det beste vorspielet - Sesong 2 - Episode 1',
            'image': 'https://img.example.com/thumb.jpg',
            'description': 'A description',
        },
    }


def _stream_json():
    return {
        'embedded': {
            'prioritizedStreams': [
                {'links': {'stream': {'href': M3U8_URL}}},
            ],
        },
    }


def test_viafree_full_extract(monkeypatch):
    """Covers lines 383-414: happy-path extraction of all metadata fields."""
    ie = _make_ie()

    fake_formats = [
        {'url': M3U8_URL, 'ext': 'mp4', 'format_id': 'main', 'tbr': 1000},
    ]
    expected_content_url = (
        'https://viafree-content.mtg-api.com/viafree-content/v1/no/path/' + PATH)

    calls = []
    sort_calls = []

    def fake_download_json(self, url_or_request, video_id, *args, **kwargs):
        calls.append((url_or_request, video_id))
        if 'viafree-content.mtg-api.com' in url_or_request:
            assert url_or_request == expected_content_url
            assert video_id == PATH
            return _content_json()
        assert url_or_request == STREAM_LINK_URL
        assert video_id == GUID
        return _stream_json()

    def fake_extract_m3u8(self, m3u8_url, video_id, ext=None, **kwargs):
        assert m3u8_url == M3U8_URL
        assert video_id == GUID
        assert ext == 'mp4'
        return fake_formats

    def fake_sort_formats(self, formats, field_preference=None):
        sort_calls.append((formats, field_preference))
        formats.sort(key=lambda f: f.get('tbr', 0), reverse=True)

    monkeypatch.setattr(ViafreeIE, '_download_json', fake_download_json)
    monkeypatch.setattr(ViafreeIE, '_extract_m3u8_formats', fake_extract_m3u8)
    monkeypatch.setattr(ViafreeIE, '_sort_formats', fake_sort_formats)

    info = ie._real_extract(URL)

    assert info == {
        'id': GUID,
        'title': 'Det beste vorspielet - Sesong 2 - Episode 1',
        'thumbnail': 'https://img.example.com/thumb.jpg',
        'description': 'A description',
        'series': 'Det beste vorspielet',
        'episode_number': 1,
        'season_number': 2,
        'duration': 1116,
        'timestamp': 1471200600,
        'formats': fake_formats,
    }
    assert sort_calls == [(fake_formats, None)]
    assert calls == [
        (expected_content_url, PATH),
        (STREAM_LINK_URL, GUID),
    ]


def test_viafree_extract_geo_restricted_403(monkeypatch):
    """Covers lines 395-398: HTTP 403 on streamLink -> geo restriction error."""
    ie = _make_ie()

    def fake_download_json(self, url_or_request, video_id, *args, **kwargs):
        if 'viafree-content.mtg-api.com' in url_or_request:
            return _content_json()
        cause = compat_HTTPError(
            url_or_request, 403, 'Forbidden', {}, io.BytesIO(b''))
        raise ExtractorError(
            'Unable to download JSON metadata: HTTP Error 403: Forbidden',
            cause=cause)

    monkeypatch.setattr(ViafreeIE, '_download_json', fake_download_json)

    with pytest.raises(GeoRestrictedError) as excinfo:
        ie._real_extract(URL)

    err = excinfo.value
    assert err.countries == [COUNTRY]
    assert 'geo restriction' in str(err).lower()


def test_viafree_extract_non_403_reraises(monkeypatch):
    """Covers the fall-through 'raise' at line 398 for non-403 errors."""
    ie = _make_ie()

    def fake_download_json(self, url_or_request, video_id, *args, **kwargs):
        if 'viafree-content.mtg-api.com' in url_or_request:
            return _content_json()
        cause = compat_HTTPError(
            url_or_request, 500, 'Server Error', {}, io.BytesIO(b''))
        raise ExtractorError('Unable to download JSON metadata', cause=cause)

    monkeypatch.setattr(ViafreeIE, '_download_json', fake_download_json)

    with pytest.raises(ExtractorError) as excinfo:
        ie._real_extract(URL)

    assert not isinstance(excinfo.value, GeoRestrictedError)
    assert isinstance(excinfo.value.cause, compat_HTTPError)
    assert excinfo.value.cause.code == 500
